package com.csust.eyediagnosis.workflow.evidence;
import org.junit.jupiter.api.Test; import org.springframework.ai.document.Document; import org.springframework.ai.vectorstore.SearchRequest; import org.springframework.ai.vectorstore.VectorStore; import java.util.List; import java.util.Map; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.*;
class GovernedVectorEvidenceRetrieverTest { @Test void sendsFixedGovernanceFilterAndFiltersBadCandidatesAgainInProcess() { VectorStore store = mock(VectorStore.class); Document legal = new Document("doc-chunk", "quote", Map.of("sourceId", "source", "sourceRevision", "r1", "chunkId", "chunk", "title", "t", "quotedTextDigest", EvidenceValues.digest("quote"), "diseaseCodes", "amd", "topicCodes", "DISEASE_OVERVIEW", "visibility", "CURATED_PUBLIC", "reviewStatus", "APPROVED", "withdrawn", false)); Document privateDoc = new Document("private", "quote", Map.of("sourceId", "private", "sourceRevision", "r1", "chunkId", "chunk", "quotedTextDigest", EvidenceValues.digest("quote"), "diseaseCodes", "amd", "topicCodes", "DISEASE_OVERVIEW", "visibility", "PRIVATE_USER", "reviewStatus", "APPROVED", "withdrawn", false)); when(store.similaritySearch(any(SearchRequest.class))).thenReturn(List.of(legal, privateDoc)); List<EvidenceCandidate> results = new GovernedVectorEvidenceRetriever(store).retrieve(EvidenceFixtures.query()); assertEquals(1, results.size()); assertTrue(GovernedVectorEvidenceRetriever.filterFor(EvidenceFixtures.query()).contains("CURATED_PUBLIC")); assertTrue(GovernedVectorEvidenceRetriever.filterFor(EvidenceFixtures.query()).contains("APPROVED")); assertTrue(GovernedVectorEvidenceRetriever.filterFor(EvidenceFixtures.query()).contains("withdrawn == false")); assertTrue(GovernedVectorEvidenceRetriever.filterFor(EvidenceFixtures.query()).contains("'amd'")); verify(store).similaritySearch(any(SearchRequest.class)); } }
